import { useEffect, useRef, useState } from 'react';
import { ease, tween } from '../../../motion/tween';
import { durations } from '../../../tokens/tokens';
import { useControllableState } from '../../../primitives/use-controllable-state';
import { Button, type ButtonProps } from '../button/Button';
import { glyphPath, glyphs, type GlyphName } from './glyphs';
import './morphing-icon-button.css';

export interface MorphingIconButtonProps extends Omit<
  ButtonProps,
  'icon' | 'children' | 'aria-pressed' | 'onChange'
> {
  /** Which pair of shapes to morph between. */
  glyph: GlyphName;
  /** Accessible name. It stays the same in both states; `aria-pressed` carries the state. */
  label: string;
  pressed?: boolean;
  defaultPressed?: boolean;
  onPressedChange?: (pressed: boolean) => void;
}

/**
 * A toggle button whose icon reshapes from one state to the other: the play triangle
 * splits into pause bars, menu bars rotate into a cross. Shapes are interpolated in
 * JavaScript, so the morph works in every browser.
 */
export function MorphingIconButton({
  glyph,
  label,
  pressed: pressedProp,
  defaultPressed = false,
  onPressedChange,
  onClick,
  ...props
}: MorphingIconButtonProps) {
  const [pressed, setPressed] = useControllableState({
    value: pressedProp,
    defaultValue: defaultPressed,
    onChange: onPressedChange,
  });
  const pathRef = useRef<SVGPathElement>(null);
  const progress = useRef(pressed ? 1 : 0);
  const shape = glyphs[glyph];
  // React renders the first shape only; the effect owns `d` afterwards, so a re-render
  // can never snap the path to its end state in the middle of a morph.
  const [initialPath] = useState(() => glyphPath(shape, pressed ? 1 : 0));

  useEffect(() => {
    const from = progress.current;
    const to = pressed ? 1 : 0;
    if (from === to) {
      pathRef.current?.setAttribute('d', glyphPath(shape, to));
      return;
    }
    return tween({
      duration: durations.glide,
      ease: ease.anchor,
      onUpdate: (t) => {
        progress.current = from + (to - from) * t;
        pathRef.current?.setAttribute('d', glyphPath(shape, progress.current));
      },
    });
  }, [pressed, shape]);

  return (
    <Button
      {...props}
      className={['atl-morph', props.className].filter(Boolean).join(' ')}
      aria-label={label}
      aria-pressed={pressed}
      onClick={(event) => {
        onClick?.(event);
        if (!event.defaultPrevented) setPressed((p) => !p);
      }}
      icon={
        <svg viewBox="0 0 24 24" width="24" height="24" className="atl-morph__glyph">
          <path ref={pathRef} d={initialPath} />
        </svg>
      }
    />
  );
}

/**
 * Two-state glyphs for the morphing icon button, drawn on a 24px grid.
 *
 * A glyph is either a set of polygons whose points correspond one to one between states
 * (interpolated point by point), or a set of bars described by centre, length, thickness and
 * angle (interpolated by parameter, so bars rotate instead of collapsing mid-way).
 */
type Point = readonly [number, number];
type Polygon = readonly Point[];

interface Bar {
  cx: number;
  cy: number;
  length: number;
  thickness: number;
  /** Degrees. */
  angle: number;
}

export type Glyph =
  | { kind: 'polygons'; from: readonly Polygon[]; to: readonly Polygon[] }
  | { kind: 'bars'; from: readonly Bar[]; to: readonly Bar[] };

export const glyphs = {
  'play-pause': {
    kind: 'polygons',
    // The play triangle is split in two so each half can become one pause bar.
    from: [
      [
        [7, 5],
        [12.5, 8.5],
        [12.5, 15.5],
        [7, 19],
      ],
      [
        [12.5, 8.5],
        [18, 12],
        [18, 12],
        [12.5, 15.5],
      ],
    ],
    to: [
      [
        [6.5, 5],
        [10.25, 5],
        [10.25, 19],
        [6.5, 19],
      ],
      [
        [13.75, 5],
        [17.5, 5],
        [17.5, 19],
        [13.75, 19],
      ],
    ],
  },
  'menu-close': {
    kind: 'bars',
    from: [
      { cx: 12, cy: 6.75, length: 16, thickness: 1.75, angle: 0 },
      { cx: 12, cy: 12, length: 16, thickness: 1.75, angle: 0 },
      { cx: 12, cy: 17.25, length: 16, thickness: 1.75, angle: 0 },
    ],
    to: [
      { cx: 12, cy: 12, length: 17, thickness: 1.75, angle: 45 },
      { cx: 12, cy: 12, length: 0, thickness: 1.75, angle: 0 },
      { cx: 12, cy: 12, length: 17, thickness: 1.75, angle: -45 },
    ],
  },
  'plus-close': {
    kind: 'bars',
    from: [
      { cx: 12, cy: 12, length: 16, thickness: 2, angle: 0 },
      { cx: 12, cy: 12, length: 16, thickness: 2, angle: 90 },
    ],
    to: [
      { cx: 12, cy: 12, length: 16, thickness: 2, angle: 45 },
      { cx: 12, cy: 12, length: 16, thickness: 2, angle: 135 },
    ],
  },
} as const satisfies Record<string, Glyph>;

export type GlyphName = keyof typeof glyphs;

const lerp = (a: number, b: number, t: number) => a + (b - a) * t;

function barPolygon({ cx, cy, length, thickness, angle }: Bar): Polygon {
  const r = (angle * Math.PI) / 180;
  const ux = Math.cos(r);
  const uy = Math.sin(r);
  const hl = length / 2;
  const ht = thickness / 2;
  return [
    [cx - ux * hl + uy * ht, cy - uy * hl - ux * ht],
    [cx + ux * hl + uy * ht, cy + uy * hl - ux * ht],
    [cx + ux * hl - uy * ht, cy + uy * hl + ux * ht],
    [cx - ux * hl - uy * ht, cy - uy * hl + ux * ht],
  ];
}

/** The glyph's polygons at progress `t` (0 = first state, 1 = second). */
export function glyphAt(glyph: Glyph, t: number): Polygon[] {
  if (glyph.kind === 'polygons') {
    return glyph.from.map((polygon, i) =>
      polygon.map(([x, y], j) => {
        const [tx, ty] = glyph.to[i]![j]!;
        return [lerp(x, tx, t), lerp(y, ty, t)] as Point;
      }),
    );
  }
  return glyph.from.map((bar, i) => {
    const to = glyph.to[i]!;
    return barPolygon({
      cx: lerp(bar.cx, to.cx, t),
      cy: lerp(bar.cy, to.cy, t),
      length: lerp(bar.length, to.length, t),
      thickness: lerp(bar.thickness, to.thickness, t),
      angle: lerp(bar.angle, to.angle, t),
    });
  });
}

export function glyphPath(glyph: Glyph, t: number): string {
  return glyphAt(glyph, t)
    .map((polygon) => `M${polygon.map(([x, y]) => `${x.toFixed(2)} ${y.toFixed(2)}`).join('L')}Z`)
    .join('');
}

@layer atlas.components {
  .atl-morph .atl-morph__glyph {
    width: 1.5em;
    height: 1.5em;
  }

  /* Filled and stroked in the same colour: the stroke rounds every corner. */
  .atl-morph__glyph path {
    fill: currentColor;
    stroke: currentColor;
    stroke-width: 1.25;
    stroke-linejoin: round;
  }

  .atl-morph[aria-pressed='true'][data-variant='secondary'],
  .atl-morph[aria-pressed='true'][data-variant='quiet'] {
    --atl-button-bg: var(--magenta-wash);
    --atl-button-edge: color-mix(in oklch, var(--chart-magenta) 60%, transparent);
  }
}

export { MorphingIconButton } from './MorphingIconButton';
export type { MorphingIconButtonProps } from './MorphingIconButton';
export { glyphAt, glyphPath, glyphs } from './glyphs';
export type { Glyph, GlyphName } from './glyphs';
